const raw = $input.first().json.output ?? '';
let parsed;
try { parsed = typeof raw === 'string' ? JSON.parse(raw.replace(/```json|```/g, '').trim()) : raw; }
catch (e) { parsed = { summary: String(raw), urgency: 'unknown', action_items: [] }; }

const mail = $('When new support email arrives').first().json;
const original = `${mail.Subject ?? ''} ${mail.text ?? mail.snippet ?? ''}`;

const patterns = {
  'email address': /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
  'IBAN': /\b[A-Z]{2}\d{2}[A-Z0-9]{10,30}\b/g,
  'phone number': /\b\+?\d[\d\s().-]{7,}\d\b/g,
};
const found = [];
for (const [label, re] of Object.entries(patterns)) {
  const n = (original.match(re) || []).length;
  if (n) found.push(`${n}× ${label}`);
}

const emoji = { high: '🔴', medium: '🟡', low: '🟢' }[String(parsed.urgency).toLowerCase()] || '⚪';
const items = (parsed.action_items || []).map(i => `• ${i}`).join('\n') || '• —';
const maskedNote = found.length
  ? `Masked before leaving your network: ${found.join(', ')}.`
  : 'No obvious PII pattern detected locally — confirm with `docker logs saklam-bridge`.';

const slack_text = [
  `${emoji} *Support summary — ${parsed.urgency ?? 'n/a'} priority*`,
  `*From:* ${mail.From ?? 'unknown'}`,
  `*Subject:* ${mail.Subject ?? '(none)'}`,
  '',
  parsed.summary ?? '',
  '',
  '*Action items:*',
  items,
  '',
  `🔒 _${maskedNote}_`,
].join('\n');

return [{ json: { slack_text, urgency: parsed.urgency ?? 'unknown', masked: found } }];
